from pathlib import Path
import base64, hashlib, json

MODEL_TASK = "A2Z-V4-ASTRA-POSTBUILD-20261006-R3-P2"
RUNTIME = Path.home() / ".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
envelope_path = RUNTIME / "model_results" / (MODEL_TASK + ".json")
if not envelope_path.is_file():
    raise SystemExit("MODEL_RESULT_MISSING")
envelope = json.loads(envelope_path.read_text(encoding="utf-8"))
checkpoint = (RUNTIME / str(envelope.get("checkpoint", ""))).resolve()
runs_root = (RUNTIME / "models/runs").resolve()
try:
    checkpoint.relative_to(runs_root)
except ValueError:
    raise SystemExit("CHECKPOINT_OUTSIDE_RUNTIME")
if not checkpoint.is_dir():
    raise SystemExit("CHECKPOINT_MISSING")

def load_json(name):
    p = checkpoint / name
    if not p.is_file():
        raise SystemExit(name.replace(".", "_").upper() + "_MISSING")
    return json.loads(p.read_text(encoding="utf-8"))

task = load_json("TASK.json")
worker = load_json("WORKER.json")
complete = load_json("COMPLETE.json")
final = complete.get("final")
review = None
if isinstance(final, str):
    try:
        review = json.loads(final)
    except json.JSONDecodeError:
        pass
elif isinstance(final, dict):
    review = final
if not isinstance(review, dict):
    events_path = checkpoint / "events.jsonl"
    if events_path.is_file():
        for line in events_path.read_text(encoding="utf-8").splitlines():
            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                continue
            item = event.get("item") if isinstance(event, dict) else None
            if event.get("type") == "item.completed" and isinstance(item, dict) and item.get("type") == "agent_message":
                text_value = item.get("text")
                if isinstance(text_value, str):
                    try:
                        candidate = json.loads(text_value)
                    except json.JSONDecodeError:
                        continue
                    if isinstance(candidate, dict):
                        review = candidate
if not isinstance(review, dict):
    raise SystemExit("REVIEW_JSON_NOT_FOUND")

payload = {
    "model_task_id": MODEL_TASK,
    "model_result_envelope": {
        "checkpoint": envelope.get("checkpoint"),
        "completion_sha256": envelope.get("completion_sha256"),
        "worker_sha256": envelope.get("worker_sha256"),
    },
    "task": {
        "task_id": task.get("task_id"),
        "phase": task.get("phase"),
        "model_policy": task.get("model_policy"),
        "astra_review_task": task.get("astra_review_task"),
    },
    "worker": {
        "model": worker.get("model"),
        "model_selection": worker.get("model_selection"),
        "thread_id": worker.get("thread_id"),
    },
    "complete": {
        "timestamp": complete.get("timestamp"),
        "thread_id": complete.get("thread_id"),
    },
    "review": review,
}
raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
encoded = base64.b64encode(raw).decode("ascii")
if len(encoded) > 24000:
    raise SystemExit("EXPORT_TOO_LARGE")
meta = {
    "kind": "ASTRA_R3P2_REVIEW",
    "model_task_id": MODEL_TASK,
    "json_bytes": len(raw),
    "base64_chars": len(encoded),
    "sha256": hashlib.sha256(raw).hexdigest(),
}
print("PREDICTION_SNAPSHOT_EXPORT_V1")
print("SNAPSHOT_EXPORT_META=" + json.dumps(meta, sort_keys=True, separators=(",", ":")))
print("SNAPSHOT_EXPORT_DATA=" + encoded)
